-  throw new Error('not implemented');
+  if (typeof text !== 'string') {
+    throw new TypeError('Input must be a string');
+  }
+
+  const units = {
+    h: 3600,
+    m: 60,
+    s: 1,
+  };
+
+  const parts = text.trim().split(/\s+/).filter(Boolean);
+
+  if (parts.length === 0) {
+    throw new RangeError('Empty string');
+  }
+
+  const seen = new Set();
+  let total = 0;
+
+  for (const part of parts) {
+    // Split on unit characters to handle "1h30m" style
+    const unitMatches = part.matchAll(/([hms])/g);
+    const unitMatchesArray = Array.from(unitMatches);
+
+    if (unitMatchesArray.length === 0) {
+      throw new RangeError(`Unknown unit or invalid format: ${part}`);
+    }
+
+    // Process each segment between unit characters
+    let lastIndex = 0;
+    for (const [, unit] of unitMatchesArray) {
+      if (seen.has(unit)) {
+        throw new RangeError(`Repeated unit: ${unit}`);
+      }
+      seen.add(unit);
+
+      // Extract the number before this unit
+      const beforeUnit = part.substring(lastIndex, part.indexOf(unit));
+      const value = parseInt(beforeUnit, 10);
+
+      if (value <= 0 || value > 999999999) {
+        throw new RangeError(`Invalid value for ${unit}: ${value}`);
+      }
+
+      total += value * units[unit];
+      lastIndex = part.indexOf(unit) + 1;
+    }
+  }
+
+  return total;
 }

